//go:build ignore

// stubgen writes handlers_stub.go: one not-implemented method for every
// StrictServerInterface operation that no other file in this package
// implements. Regenerated by go generate, so implementing a handler and
// regenerating removes its stub, and an operation can never be silently
// missing from the server.
package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

var (
	interfaceStart = "type StrictServerInterface interface {"
	methodLine     = regexp.MustCompile(`^\s*([A-Za-z0-9]+)\(ctx context\.Context, request ([A-Za-z0-9]+)\) \(([A-Za-z0-9]+), error\)`)
	implemented    = regexp.MustCompile(`func \(s \*Server\) ([A-Za-z0-9]+)\(`)
)

func main() {
	generated, err := os.ReadFile("generated.gen.go")
	if err != nil {
		log.Fatal(err)
	}
	text := string(generated)
	start := strings.Index(text, interfaceStart)
	if start < 0 {
		log.Fatal("StrictServerInterface not found")
	}
	end := strings.Index(text[start:], "\n}\n")
	block := text[start : start+end]

	type method struct{ name, request, response string }
	var methods []method
	for _, line := range strings.Split(block, "\n") {
		if m := methodLine.FindStringSubmatch(line); m != nil {
			methods = append(methods, method{m[1], m[2], m[3]})
		}
	}

	have := map[string]bool{}
	files, _ := filepath.Glob("*.go")
	for _, file := range files {
		if file == "handlers_stub.go" || file == "generated.gen.go" {
			continue
		}
		data, err := os.ReadFile(file)
		if err != nil {
			log.Fatal(err)
		}
		for _, m := range implemented.FindAllStringSubmatch(string(data), -1) {
			have[m[1]] = true
		}
	}

	var b strings.Builder
	b.WriteString("// Code generated by stubgen.go; DO NOT EDIT.\n")
	b.WriteString("//\n// Every operation the contract declares and no slice has implemented yet.\n")
	b.WriteString("// Implement the method on *Server in another file and run go generate to\n")
	b.WriteString("// drop its stub.\n\n")
	b.WriteString("package httpapi\n\nimport \"context\"\n\n")
	sort.Slice(methods, func(i, j int) bool { return methods[i].name < methods[j].name })
	count := 0
	for _, m := range methods {
		if have[m.name] {
			continue
		}
		count++
		fmt.Fprintf(&b, "// %s is not implemented yet.\nfunc (s *Server) %s(_ context.Context, _ %s) (%s, error) {\n\treturn nil, notImplemented(%q)\n}\n\n",
			m.name, m.name, m.request, m.response, m.name)
	}
	if count == 0 {
		b.Reset()
		b.WriteString("// Code generated by stubgen.go; DO NOT EDIT.\n//\n// Every operation is implemented.\n\npackage httpapi\n")
	}
	if err := os.WriteFile("handlers_stub.go", []byte(b.String()), 0o644); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("stubgen: %d of %d operations stubbed\n", count, len(methods))
}
